insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('bcf1aa45-924e-55b0-8d07-3f42e4e9d3f0', 'wg6-paragraph-transitions-p05', (select id from public.skills where slug = 'write-g6-paragraph-transitions'), null,
        '6-8', $q$Making a Clay Animation$q$, $q$(1) A stop-motion movie makes clay figures seem to move on their own. (2) To make one, you need a camera on a stand, some modeling clay, and plenty of patience. (3) Start by shaping a simple character, such as a frog or a snail. (4) Next, set the character on a table and take one photo. (5) ____, move the character a tiny bit and take another photo. (6) Repeat these two steps again and again until the scene is finished.

(7) When the photos are played quickly, one after another, your eyes blend them into smooth motion. (8) This trick takes a lot of work. (9) For example, a scene that lasts only ten seconds can need more than one hundred photos. (10) Modeling clay comes in many bright colors, such as green and orange. (11) ____, animators may spend a whole afternoon creating just a few seconds of film.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
