  ('2579dc61-8b95-580d-bf06-1cbef34fe585', null, (select id from public.skills where slug = 'write-g6-precise-language'), null, 'hard',
   $q$A student is writing an email to a summer camp director to ask when swimming lessons start each day. Which opening sentence is polite and formal and also states the purpose precisely?$q$, $q$[{"text":"I am writing to ask what time the swimming lessons begin each day.","is_correct":true},{"text":"Hey, so what is the deal with the swimming stuff?","is_correct":false,"misconception_token":"informal-vague"},{"text":"Tell me right now when the swimming lessons start.","is_correct":false,"misconception_token":"demanding-tone"},{"text":"I am writing to ask a question about something at camp.","is_correct":false,"misconception_token":"vague-purpose"}]$q$::jsonb, $q$I am writing to ask what time the swimming lessons begin each day.$q$, $q$This sentence is polite and names exactly what the student wants to know. "I am writing to ask a question about something at camp" is formal, but "something at camp" does not tell the director what the question is.$q$, 'draft', null)
