-- Passage wg6-writing-with-evidence-p01
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('57c6f2bc-8caf-5da4-a17a-ba763a6c770e', 'wg6-writing-with-evidence-p01', (select id from public.skills where slug = 'write-g6-writing-with-evidence'), null,
        '6-8', $q$Draft: The Long Trip of the Monarchs$q$, $q$(1) In the article "A Long Trip on Thin Wings," Ayesha Rahman explains how monarch butterflies travel thousands of miles each fall. (2) ____. (3) Rahman writes that monarchs fly south to the same mountain forests every year, even though no single butterfly has made the trip before. (4) She explains that the butterflies use the position of the sun to keep flying in the right direction. (5) This detail shows that monarchs are born with a kind of built-in compass.

(6) Monarchs also need help from the land along the way. (7) Rahman reports that the butterflies stop to drink nectar from fall flowers so they have enough energy to keep going. (8) My grandmother has a painting of a purple butterfly in her kitchen. (9) Rahman notes that in areas where fields of wildflowers were replaced by parking lots, fewer monarchs were counted. (10) ____, the trip depends on flowers being there when the butterflies need them.

(11) Monarchs are pretty.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
insert into public.generated_questions
  (id, template_id, skill_id, sat_alignment, difficulty, stem, choices, correct_answer, solution, status, passage_id)
values
  ('0d299fd2-410c-55d8-9066-db7ec16e8541', null, (select id from public.skills where slug = 'write-g6-writing-with-evidence'), null, 'easy',
   $q$Which sentence best fills blank (2) as the claim of the draft?$q$, $q$[{"text":"Rahman shows that the monarchs' trip depends on their natural sense of direction and on finding flowers along the way.","is_correct":true},{"text":"Monarch butterflies are orange and black insects that live in many parts of North America.","is_correct":false,"misconception_token":"topic-not-claim"},{"text":"Rahman thinks that towns should stop building parking lots anywhere near open fields.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Butterflies are my favorite insects to watch when I play outside in the summer.","is_correct":false,"misconception_token":"opinion-not-analysis"}]$q$::jsonb, $q$Rahman shows that the monarchs' trip depends on their natural sense of direction and on finding flowers along the way.$q$, $q$Paragraph 1 is about the monarchs' sense of direction and paragraph 2 is about flowers along the route, so a claim naming both fits the draft. The draft never says Rahman wants towns to stop building parking lots, so that choice goes beyond the text.$q$, 'draft', '57c6f2bc-8caf-5da4-a17a-ba763a6c770e')
