values
  ('71369b41-71bf-5f25-96a9-d22364aa07ad', null, (select id from public.skills where slug = 'write-g6-writing-with-evidence'), null, 'medium',
   $q$Which revision of sentence 11 would best conclude the draft?$q$, $q$[{"text":"Some other butterflies, such as painted ladies, also travel long distances each year.","is_correct":false,"misconception_token":"off-topic-fact"},{"text":"Monarchs are pretty, and many people enjoy seeing them in their gardens every fall.","is_correct":false,"misconception_token":"opinion-not-analysis"},{"text":"Rahman writes that monarchs use the position of the sun to steer in the right direction.","is_correct":false,"misconception_token":"evidence-without-analysis"},{"text":"Rahman's evidence shows that monarchs finish their trip only when their sense of direction is matched by flowers on the route.","is_correct":true}]$q$::jsonb, $q$Rahman's evidence shows that monarchs finish their trip only when their sense of direction is matched by flowers on the route.$q$, $q$A strong conclusion sums up the analysis from both paragraphs, and only the choice about direction being matched by flowers joins both ideas. Restating the detail about the sun repeats one piece of evidence without pulling the draft together.$q$, 'draft', '57c6f2bc-8caf-5da4-a17a-ba763a6c770e')
