-- Passage wg6-writing-with-evidence-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('29ffc352-e7dd-5e28-84ac-45689addf0a8', 'wg6-writing-with-evidence-p02', (select id from public.skills where slug = 'write-g6-writing-with-evidence'), null,
        '6-8', $q$Draft: Paper Made by Hand$q$, $q$(1) Mateo Okafor's article "From Bark to Page" describes how paper was made by hand long before there were paper factories. (2) Okafor shows that making paper by hand was slow, careful work that turned simple plants into something valuable. (3) He explains that workers soaked tree bark and old cloth in water for many days until the fibers became soft. (4) ____. (5) Okafor writes that "a single worker might make only a few hundred sheets in a full day." (6) This shows that every sheet took time and skill.

(7) Because paper took so long to make, people treated it with care. (8) Okafor reports that families often reused the backs of letters and saved scraps to patch old books. (9) Today I use way too much paper in my notebooks. (10) He also notes that some towns hired guards to protect their paper storehouses. (11) These details show ____.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
