  ('93581b02-fcae-5c17-9cd4-46e5875c149c', null, (select id from public.skills where slug = 'write-g6-writing-with-evidence'), null, 'easy',
   $q$Which sentence best fills blank (2) as the claim of the draft?$q$, $q$[{"text":"Delgado believes that cafeteria workers do not know how to cook good meals.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"School cafeterias serve lunch to hundreds of hungry students every single day.","is_correct":false,"misconception_token":"topic-not-claim"},{"text":"Delgado says that the school used to throw away forty pounds of food a day.","is_correct":false,"misconception_token":"too-narrow"},{"text":"Delgado shows that letting students help plan lunches cut food waste and taught them useful skills.","is_correct":true}]$q$::jsonb, $q$Delgado shows that letting students help plan lunches cut food waste and taught them useful skills.$q$, $q$Paragraph 1 is about less food waste and paragraph 2 is about new skills, so the claim should name both. The forty pounds detail is a single piece of evidence, so it is too narrow to be the claim.$q$, 'draft', '1f43b476-1777-55fc-a3eb-dd2219c2ef77')
