insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('7ae270f9-354d-5e65-a996-1c19e1be7c85', 'wg7-argument-writing-p05', (select id from public.skills where slug = 'write-g7-argument-writing'), null,
        '6-8', $q$Students Can Fix It$q$, $q$(1) At Lakeside Middle School, broken laptops sit in a cart for weeks because one technician serves all five schools in our district. (2) Lakeside should create a student tech help desk where trained students handle simple laptop repairs. (3) Most problems are small, such as a loose key, a forgotten password, or a program that will not open. (4) Last year, the technician's log showed that 70 percent of repair requests at Lakeside took less than ten minutes to fix. (5) ______ students could solve these problems during study hall and return laptops the same day. (6) Students on the help desk would also learn real skills that could lead to careers in technology.

(7) Some parents worry that students might damage the laptops further. (8) To prevent this, the help desk would handle only simple tasks, and anything that requires opening a laptop case would still go to the technician. (9) Our neighboring school, Pine Hill, has run a similar desk for two years with no reports of damaged equipment.

(10) Laptops are really important for school.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
